import { defineConfig } from "vitest/config";

/** Every metric must stay fully covered; CI runs `npm run test:coverage`, so a drop fails the build. */
const FULL_COVERAGE_PERCENT = 100;

export default defineConfig({
  test: {
    globals: true,
    environment: "node",
    include: ["src/**/*.test.ts"],
    coverage: {
      provider: "v8",
      include: ["src/**/*.ts"],
      exclude: [
        "src/**/*.test.ts",
        // Generated by graphql-codegen (`npm run generate`); never hand-edited.
        "src/types/unraid/**",
        // Helpers used only by tests.
        "src/tools/_shared/test-support.ts",
        // Process entry point: reads the environment and wires transports together.
        "src/index.ts",
      ],
      // json-summary feeds the README badge (see the coverage-badge job in ci.yml).
      reporter: ["text-summary", "json-summary"],
      thresholds: {
        lines: FULL_COVERAGE_PERCENT,
        statements: FULL_COVERAGE_PERCENT,
        functions: FULL_COVERAGE_PERCENT,
        branches: FULL_COVERAGE_PERCENT,
      },
    },
  },
});
